#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET -1
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

// Пины
#define GEIGER_PIN 2   // выход импульсов с платы СБМ-20 (INT0)
#define BUZZER_PIN 3   // активный зуммер
#define ENABLE_BUZZER true

// Калибровочный коэффициент для СБМ-20-1:
// примерно 151 CPM = 1 мкЗв/ч, т.е. 1 CPM ≈ 0.0066 мкЗв/ч
#define USV_PER_CPM 0.0066f

volatile unsigned long pulseCount = 0;
volatile unsigned long lastPulseMicros = 0;
volatile bool beepRequest = false;

const unsigned long DEBOUNCE_US = 200;   // антидребезг 200 мкс
const unsigned long BEEP_MS = 5;         // длительность щелчка зуммера

unsigned long countsPerSecond[60] = {0};
unsigned long lastSecondMillis = 0;
unsigned long lastReportedCount = 0;
unsigned long cpm = 0;
float doseRate = 0.0;

bool beepActive = false;
unsigned long beepStartMillis = 0;

// Прерывание по импульсу от трубки
void countPulse() {
  unsigned long m = micros();
  if (m - lastPulseMicros > DEBOUNCE_US) {
    pulseCount++;
    lastPulseMicros = m;
    if (ENABLE_BUZZER) beepRequest = true;
  }
}

void setup() {
  pinMode(GEIGER_PIN, INPUT_PULLUP);
  pinMode(BUZZER_PIN, OUTPUT);
  digitalWrite(BUZZER_PIN, LOW);

  Serial.begin(9600);

  // Инициализация OLED (адрес 0x3C, при необходимости 0x3D)
  if(!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    while (1); // дисплей не найден
  }

  display.clearDisplay();
  display.setTextSize(2);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(10, 10);
  display.println("Geiger");
  display.setCursor(10, 30);
  display.println("Counter");
  display.display();
  delay(2000);

  // Прерывание по спаду импульса (если выход активный высокий — поменяйте на RISING)
  attachInterrupt(digitalPinToInterrupt(GEIGER_PIN), countPulse, FALLING);

  lastSecondMillis = millis();
  lastReportedCount = pulseCount;
}

void loop() {
  // Короткий звуковой щелчок на каждый импульс
  if (beepRequest) {
    beepRequest = false;
    digitalWrite(BUZZER_PIN, HIGH);
    beepActive = true;
    beepStartMillis = millis();
  }
  if (beepActive && (millis() - beepStartMillis >= BEEP_MS)) {
    digitalWrite(BUZZER_PIN, LOW);
    beepActive = false;
  }

  // Расчёт CPM раз в секунду
  unsigned long now = millis();
  if (now - lastSecondMillis >= 1000) {
    lastSecondMillis += 1000;

    // Сдвигаем секундные отсчёты
    for (int i = 59; i > 0; i--) {
      countsPerSecond[i] = countsPerSecond[i - 1];
    }
    unsigned long currentTotal = pulseCount;
    countsPerSecond[0] = currentTotal - lastReportedCount;
    lastReportedCount = currentTotal;

    // Сумма импульсов за последние 60 секунд
    unsigned long sum = 0;
    for (int i = 0; i < 60; i++) {
      sum += countsPerSecond[i];
    }
    cpm = sum;
    doseRate = cpm * USV_PER_CPM;

    updateDisplay();

    Serial.print("CPM: ");
    Serial.print(cpm);
    Serial.print("  Dose: ");
    Serial.print(doseRate, 3);
    Serial.println(" uSv/h");
  }
}

void updateDisplay() {
  display.clearDisplay();

  display.setTextSize(1);
  display.setCursor(0, 0);
  display.print("CPM:");

  display.setTextSize(2);
  display.setCursor(40, 0);
  display.print(cpm);

  display.setTextSize(1);
  display.setCursor(0, 22);
  display.print("Dose: ");
  display.print(doseRate, 3);
  display.print(" uSv/h");

  display.setCursor(0, 36);
  display.print("Total: ");
  display.print(pulseCount);

  display.display();
}
